function extraerUltimoJson(text) {
  const lastClose = text.lastIndexOf('}');
  if (lastClose === -1) return null;
  let depth = 0;
  for (let i = lastClose; i >= 0; i--) {
    if (text[i] === '}') depth++;
    else if (text[i] === '{') {
      depth--;
      if (depth === 0) {
        const candidate = text.slice(i, lastClose + 1);
        try { return JSON.parse(candidate); } catch (e) { return null; }
      }
    }
  }
  return null;
}

const raw = $json.output || '';
let parsed = extraerUltimoJson(raw);
if (!parsed || !['resuelto', 'fallido', 'requiere_intervencion'].includes(parsed.decision)) {
  parsed = { decision: 'fallido', diagnostico: 'El agente no devolvió un JSON válido (o falló la llamada al modelo).', accion: 'Sin acción — respuesta inválida o error del modelo.' };
}
const source = $('Normalizar Pendientes').first().json;
return [{ json: { ...source, decision: parsed.decision, diagnostico: parsed.diagnostico, accion: parsed.accion } }];

const historial = $json.historial || [];

let informeHtml = '';
if (Array.isArray(historial) && historial.length > 0) {
  informeHtml = historial.map(h => {
    const fecha = h.fecha || '';
    const intento = h.intento || '';
    const resultadoLabel = h.resultado === 'resuelto' ? '✅ Resuelto' : '❌ Fallido';
    const diagnostico = (h.diagnostico || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const accion = (h.accion || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    return `<p style="margin: 16px 0 6px 0; font-size: 14px; font-weight: 600; color: #212529;">Intento ${intento} · ${fecha}</p>\n<ul style="margin: 0 0 8px 0; padding-left: 20px; font-size: 13px; color: #495057; line-height: 1.6;">\n  <li><strong>Diagnóstico:</strong> ${diagnostico}</li>\n  <li><strong>Acción:</strong> ${accion}</li>\n  <li><strong>Resultado:</strong> ${resultadoLabel}</li>\n</ul>`;
  }).join('\n');
} else {
  informeHtml = '<p style="margin:0; font-size: 13px; color: #6c757d;">Sin historial disponible.</p>';
}

const ultimo = Array.isArray(historial) && historial.length > 0 ? historial[historial.length - 1] : null;
if (ultimo) {
  const diagUltimo = (ultimo.diagnostico || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const accionUltimo = (ultimo.accion || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  informeHtml += `<p style="margin: 16px 0 0 0; font-size: 14px; color: #212529; line-height: 1.6;"><strong>Recomendación:</strong> ${diagUltimo} ${accionUltimo}</p>`;
}

return [{ json: { ...$json, informeHtml } }];
